additionalFields.caption:
={{ "<b>Post deleted</b>
" + ($('Log: mark deleted').first().json.media_type ? ({"NONE":"Text post","ARTICLE":"Article post","IMAGE":"Image post","MULTI_IMAGE":"Multi-image post"}[$('Log: mark deleted').first().json.media_type] ?? "Post") + " · " : "") + $now.setZone($now.zone).toFormat("ccc d LLL, HH:mm") + "

" + "<blockquote expandable>" + String($('Log: mark deleted').first().json.text ?? "").slice(0,700).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;") + (String($('Log: mark deleted').first().json.text ?? "").length > 700 ? "…" : "") + "</blockquote>" }}

