assignments.value:
={{ (() => { const rows = $input.all().map(i => i.json).filter(j => j.id !== undefined && j.id !== null); const one = r => { const t = String(r.text ?? "").replace(/\s+/g, " ").trim(); return "#" + r.id + " · " + (t.slice(0, 120) + (t.length > 120 ? "…" : "")).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }; return rows.length ? "<b>Open ideas</b> · latest " + rows.length + "

" + rows.map((r, i) => (i + 1) + ". " + one(r)).join("
") : "No open ideas yet."; })() }}

